mapper.select:
SELECT n.id, n.ms_monitor_metric_network_monitor_id, n.ms_monitor_metric_network_interface_name, n.ms_monitor_metric_network_rx_bytes, n.ms_monitor_metric_network_tx_bytes, n.ms_monitor_metric_network_speed_bps, n.ms_monitor_metric_network_collect_time FROM ms_monitor_metric_network n INNER JOIN ( SELECT ms_monitor_metric_network_interface_name, MAX(ms_monitor_metric_network_collect_time) AS collect_time FROM ms_monitor_metric_network WHERE ms_monitor_metric_network_monitor_id = #{monitorId} AND ms_monitor_metric_network_collect_time < #{collectTime} AND ms_monitor_metric_network_interface_name IN
#{interfaceName}
GROUP BY ms_monitor_metric_network_interface_name ) previous ON previous.ms_monitor_metric_network_interface_name = n.ms_monitor_metric_network_interface_name AND previous.collect_time = n.ms_monitor_metric_network_collect_time WHERE n.ms_monitor_metric_network_monitor_id = #{monitorId} ORDER BY n.ms_monitor_metric_network_collect_time DESC, n.id DESC
